mapper.select:
SELECT user_id, factory_code FROM sn_user_factory WHERE user_id IN
#{id}
ORDER BY factory_code

mapper.update:
UPDATE sn_user SET password_hash = #{hash}, must_change_pwd = 0, pwd_changed_at = #{pwdChangedAt},
  updated_at = #{now}
WHERE id = #{id}

UPDATE sn_user SET name = #{name}, role = #{role}, factory_code = #{factoryCode}, ip_whitelist = #{ipWhitelist},
  updated_at = #{now}
WHERE id = #{id}

UPDATE sn_user SET password_hash = #{hash}, secret_sealed = #{sealed}, pwd_changed_at = #{pwdChangedAt},
  auth_failures = 0, locked_until = NULL, updated_at = #{now}
WHERE id = #{id}

UPDATE sn_user SET role = 'admin', factory_code = NULL, status = 'ACTIVE', password_hash = #{hash},
  must_change_pwd = 0, pwd_changed_at = #{pwdChangedAt}, disabled_by = NULL, disabled_at = NULL,
  updated_at = #{now}
WHERE id = #{id}
